class Solution:
    def mirrorReflection(self, p: int, q: int) -> int:
        x, y, dx, dy = 0, 0, p, q
        while True:
            x += dx
            y += dy
            if y == p or y == 0:
                if x == p:
                    return 2 if y == p else 0
                else:
                    return 1 if y == p else -1
            if x == p:
                dx = -dx
            elif x == 0:
                dx = -dx
            if y > p:
                dy = -dy
                y = 2 * p - y
            elif y < 0:
                dy = -dy
                y = -y

