class Solution {
    public int mirrorReflection(int p, int q) {
        int g = gcd(p, q);
        int m = (p / g) % 2;
        int n = (q / g) % 2;
        if (m == 1 && n == 1) return 2;
        if (m == 1) return 1;
        return 0;
    }
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

